import React, { useEffect, useState } from 'react';

// Invoices feature: one place listing every invoice across all projects, showing which project each
// is for and what stage (status) it is at. Owns its own state (CLAUDE.md — features own their
// state, no global store). The list has grown large, so it is shown a PAGE AT A TIME (10 per page)
// with next/previous controls; the page slice, project-name join and stage filter are done
// server-side (GET /api/invoices/all?page=&status=).
type InvoiceListing = {
  id: number;
  projectId: number;
  projectName: string;
  amount: number;
  status: string;
};

type InvoicePage = {
  invoices: InvoiceListing[];
  total: number;
  page: number;
  pageSize: number;
};

function money(n: number): string {
  return Number(n).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
}

// The lifecycle stages an invoice can sit at (see V5/V8 migrations: DRAFT -> SENT -> PAID). The
// filter narrows the all-invoices list to one stage; the empty value keeps every stage visible.
const STAGES = ['DRAFT', 'SENT', 'PAID'];

export function AllInvoicesPage() {
  const [invoices, setInvoices] = useState<InvoiceListing[]>([]);
  const [total, setTotal] = useState<number>(0);
  const [pageSize, setPageSize] = useState<number>(10);
  const [page, setPage] = useState<number>(1);
  const [stage, setStage] = useState<string>('');

  useEffect(() => {
    async function load() {
      const params = new URLSearchParams({ page: String(page) });
      if (stage) {
        params.set('status', stage);
      }
      const res = await fetch(`/api/invoices/all?${params.toString()}`);
      if (res.ok) {
        const data: InvoicePage = await res.json();
        setInvoices(data.invoices);
        setTotal(data.total);
        setPageSize(data.pageSize);
      }
    }
    void load();
  }, [page, stage]);

  // Changing the stage filter starts again from the first page so the count and page number stay
  // consistent with what is shown.
  function changeStage(next: string): void {
    setStage(next);
    setPage(1);
  }

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  return (
    <section data-testid="all-invoices-page">
      <h1>Invoices</h1>
      <label>
        Stage
        <select
          data-testid="invoice-status-filter"
          value={stage}
          onChange={(e) => changeStage(e.target.value)}
        >
          <option value="">All stages</option>
          {STAGES.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>
      </label>
      {total === 0 ? (
        <p data-testid="all-invoices-empty">No invoices yet.</p>
      ) : (
        <>
          <table data-testid="all-invoices-table">
            <thead>
              <tr>
                <th>Project</th>
                <th>Amount</th>
                <th>Stage</th>
              </tr>
            </thead>
            <tbody>
              {invoices.map((inv) => (
                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
                  <td data-testid="invoice-project">{inv.projectName}</td>
                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
                  <td data-testid="invoice-status">{inv.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <nav data-testid="invoice-pager">
            <button
              type="button"
              data-testid="invoice-page-prev"
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              Previous
            </button>
            <span data-testid="invoice-page-label">{page}</span>
            <button
              type="button"
              data-testid="invoice-page-next"
              disabled={page >= totalPages}
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            >
              Next
            </button>
          </nav>
        </>
      )}
    </section>
  );
}

import React, { useEffect, useState } from 'react';

// A client's projects, shown when a client is opened from the clients list. Owns its own state
// (CLAUDE.md — features own their state; clients does not import the projects feature). Reuses the
// project-row-<id>/project-name anchors so the projects listing reads the same in this context.
type Project = { id: number; name: string; clientId: number; clientName: string };

export function ClientProjects({ clientId }: { clientId: number }) {
  const [projects, setProjects] = useState<Project[]>([]);
  // Show only ACTIVE (and non-archived) projects by default; the toggle reveals every status,
  // archived (hidden) ones included — that is the "also see finished and hidden" ask.
  const [showAll, setShowAll] = useState(false);

  async function load(all: boolean) {
    const query = all
      ? `clientId=${clientId}&includeArchived=true`
      : `clientId=${clientId}&status=ACTIVE`;
    const res = await fetch(`/api/projects?${query}`);
    if (res.ok) {
      setProjects(await res.json());
    }
  }

  useEffect(() => {
    void load(showAll);
  }, [clientId, showAll]);

  return (
    <section data-testid="client-projects">
      <h2>Projects</h2>
      <button
        type="button"
        data-testid="client-projects-show-all"
        aria-pressed={showAll}
        onClick={() => setShowAll((v) => !v)}
      >
        {showAll ? 'Show active only' : 'Show finished and hidden'}
      </button>
      {projects.length === 0 ? (
        <p data-testid="client-projects-empty">No projects yet.</p>
      ) : (
        <table data-testid="client-projects-table">
          <thead>
            <tr>
              <th>Name</th>
            </tr>
          </thead>
          <tbody>
            {projects.map((p) => (
              <tr key={p.id} data-testid={`project-row-${p.id}`}>
                <td data-testid="project-name">{p.name}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

